    @app.post("/nights")
    def add_night(
        request: Request,
        bedtime: str = Form(...),
        wake_time: str = Form(...),
        timezone: str = Form(...),
        notes: str = Form(""),
    ):
        try:
            diary.add_night(
                Night(
                    bedtime=local_input_to_aware(bedtime, timezone),
                    wake_time=local_input_to_aware(wake_time, timezone),
                    timezone=timezone,
                    notes=notes.strip(),
                )
            )
